contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property test
    // params:
    //  - depositAmount: amount of wei to send in deposit call
    //  - withdrawAmount: amount to attempt to withdraw
    //  - doRefund: if nonzero, call refund() instead of withdraw
    function run(uint256 depositAmount, uint256 withdrawAmount, uint256 doRefund) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");

        // read starting values
        uint256 beforeContractBalance = address(c).balance;
        // balances mapping is not public in C, so we observe via behavior: there is no getter.
        // However, C's deposit and withdraw affect address(c).balance and observable transfer to this contract.

        // perform deposit from this contract to C
        c.deposit{value: depositAmount}();

        uint256 afterDepositContractBalance = address(c).balance;

        // after deposit, contract balance must have increased by depositAmount
        // (we cannot assert here; instead we'll use this info in final assert)

        bool withdrewReverted;
        uint256 beforeThisBalance = address(this).balance;
        // Try either withdraw(withdrawAmount) or refund() depending on doRefund
        if (doRefund == 0) {
            try c.withdraw(withdrawAmount) {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        } else {
            // call refund
            try c.refund() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        }

        uint256 afterThisBalance = address(this).balance;
        uint256 afterContractFinal = address(c).balance;

        // General rule asserted:
        // 1) After deposit, the contract's balance increased by depositAmount.
        // 2) If withdraw/refund succeeded, the sum of (change in this contract balance) and (change in c balance)
        //    must be zero (Ether conserved between them) and the change in c balance equals negative of Ether received.
        // 3) If withdraw reverted, contract balances remain as after deposit (no further change).
        assert(
            // part A: deposit effect observed
            afterDepositContractBalance == beforeContractBalance + depositAmount
            &&
            (
                // either the withdraw/refund reverted and no balances changed afterward
                (withdrewReverted && afterContractFinal == afterDepositContractBalance && afterThisBalance == beforeThisBalance)
                ||
                // or it succeeded and Ether moved from c to this contract conserving total between them
                (!withdrewReverted &&
                    // change in c balance equals negative change in this contract balance
                    (int256(afterContractFinal) - int256(afterDepositContractBalance) == -(int256(afterThisBalance) - int256(beforeThisBalance)))
                )
            )
        );
    }

    // Allow this contract to receive Ether from c.transfer
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property test
    // Params:
    //  - depositAmount: amount of wei to send with deposit()
    //  - withdrawAmount: amount to attempt to withdraw
    //  - doRefund: if nonzero, call refund() instead of withdraw(amount)
    function run(uint256 depositAmount, uint256 withdrawAmount, uint256 doRefund) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");

        // observe starting balances
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeThisBalance = address(this).balance;

        // perform deposit (top-level state-changing call)
        c.deposit{value: depositAmount}();

        // observe after deposit
        uint256 afterDepositContractBalance = address(c).balance;
        uint256 afterDepositThisBalance = address(this).balance;

        // prepare to call withdraw or refund and record whether it reverted
        bool callReverted;
        // perform withdraw or refund as separate top-level statements using try/catch
        if (doRefund == 0) {
            try c.withdraw(withdrawAmount) {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        } else {
            try c.refund() {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        }

        // observe final balances
        uint256 finalContractBalance = address(c).balance;
        uint256 finalThisBalance = address(this).balance;

        // General rule asserted:
        // 1) Deposit increased c balance exactly by depositAmount and decreased this contract by depositAmount.
        // 2) If the subsequent withdraw/refund reverted, balances remain as after deposit.
        // 3) If it succeeded, Ether conserved between c and this: c balance decreased by exactly the positive amount
        //    that this contract gained in that step, and that amount is <= afterDepositContractBalance.
        assert(
            // part 1: deposit effect
            afterDepositContractBalance == beforeContractBalance + depositAmount
            && afterDepositThisBalance + depositAmount == beforeThisBalance

            // part 2 and 3: effect of withdraw/refund
            && (
                (callReverted && finalContractBalance == afterDepositContractBalance && finalThisBalance == afterDepositThisBalance)
                || (!callReverted && (
                    // amount moved from c to this contract in the call
                    (afterDepositContractBalance - finalContractBalance) == (finalThisBalance - afterDepositThisBalance)
                    // and c could not have sent more than it had after deposit
                    && (finalThisBalance - afterDepositThisBalance) <= afterDepositContractBalance
                ))
            )
        );
    }

    // allow receiving Ether from c.transfer
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    //  depositAmount: amount to send with deposit()
    //  withdrawAmount: amount to pass to withdraw()
    //  doRefund: if nonzero call refund(), else call withdraw(withdrawAmount)
    function run(uint256 depositAmount, uint256 withdrawAmount, uint256 doRefund) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // observe starting balances
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeThisBalance = address(this).balance;

        // perform deposit as a top-level state-changing call
        c.deposit{value: depositAmount}();

        // observe after deposit
        uint256 afterDepositContractBalance = address(c).balance;
        uint256 afterDepositThisBalance = address(this).balance;

        // perform withdraw or refund as a top-level state-changing call, capturing revert via try/catch
        bool callReverted;
        if (doRefund == 0) {
            try c.withdraw(withdrawAmount) {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        } else {
            try c.refund() {
                callReverted = false;
            } catch {
                callReverted = true;
            }
        }

        // observe final balances
        uint256 finalContractBalance = address(c).balance;
        uint256 finalThisBalance = address(this).balance;

        // Assert the invariant:
        // - deposit increased contract by depositAmount and decreased this by depositAmount
        // - if the subsequent call reverted, balances stayed as after deposit
        // - if it succeeded, the decrease in contract balance equals the increase in this contract's balance
        //   (i.e., Ether moved exactly between them)
        assert(
            afterDepositContractBalance == beforeContractBalance + depositAmount
            && afterDepositThisBalance + depositAmount == beforeThisBalance
            && (
                (callReverted && finalContractBalance == afterDepositContractBalance && finalThisBalance == afterDepositThisBalance)
                || (!callReverted && (afterDepositContractBalance - finalContractBalance) == (finalThisBalance - afterDepositThisBalance))
            )
        );
    }

    // allow receiving Ether from c.transfer
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmount: amount to send with deposit()
    // withdrawAmount: amount to attempt to withdraw
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        // need funds to perform deposit
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // observe before-values
        uint256 beforeContractBalance = address(c).balance;
        // balances(address) has no getter (it's private), but C's public surface doesn't expose per-address balances.
        // However, we can only observe address(c).balance and whether withdraw reverts. We will rely on that.

        // perform deposit as a top-level state-changing call
        c.deposit{value: depositAmount}();

        // observe after deposit
        uint256 afterDepositContractBalance = address(c).balance;

        // attempt withdraw and capture whether it reverted
        bool withdrew;
        try c.withdraw(withdrawAmount) {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // observe final contract balance
        uint256 finalContractBalance = address(c).balance;

        // General rule:
        // - deposit increased contract balance by depositAmount
        // - if withdraw succeeded then contract balance decreased by exactly withdrawAmount
        // - if withdraw reverted then contract balance stayed the same as after deposit
        assert(
            afterDepositContractBalance == beforeContractBalance + depositAmount
            && (
                (withdrew && afterDepositContractBalance == finalContractBalance + withdrawAmount)
                || (!withdrew && finalContractBalance == afterDepositContractBalance)
            )
        );
    }

    // allow receiving Ether from c.transfer
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmt: amount to send in deposit(); withdrawAmt: amount to attempt to withdraw
    function run(uint256 depositAmt, uint256 withdrawAmt) public payable {
        // need funds to perform deposit if depositAmt > 0
        require(address(this).balance >= depositAmt, "insufficient balance for deposit");

        // observe contract balance before any actions
        uint256 before = address(c).balance;

        // perform deposit if requested
        if (depositAmt > 0) {
            c.deposit{value: depositAmt}();
        }

        // observe balance after deposit phase
        uint256 afterDeposit = address(c).balance;

        // attempt withdraw and record whether it reverted
        bool didRevert;
        try c.withdraw(withdrawAmt) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // observe final balance
        uint256 finalBal = address(c).balance;

        // General rule: deposit increased by depositAmt; if withdraw succeeded contract balance decreased by exactly withdrawAmt, else unchanged.
        assert(
            afterDeposit == before + depositAmt
            && (
                (didRevert && finalBal == afterDeposit)
                || (!didRevert && finalBal + withdrawAmt == afterDeposit)
            )
        );
    }

    // allow receiving Ether from C.transfer
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function driving C
    function run(uint256 depositAmt, uint256 withdrawAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance");

        // record balances before interactions
        uint256 beforeContractBal = address(c).balance;
        // note: balances mapping is private in C; we can only observe effects via contract balance and by attempting withdraw

        // perform deposit to C from this contract
        c.deposit{value: depositAmt}();

        uint256 afterDepositContractBal = address(c).balance;

        // attempt withdraw and capture whether it reverted
        bool reverted;
        try c.withdraw(withdrawAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterContractBal = address(c).balance;

        // General rule: If withdraw succeeded, contract balance decreased by exactly withdrawAmt (up to available funds deposited by this caller)
        // If withdraw reverted, contract balance stays the same as after deposit.
        // Also, contract balance should equal beforeContractBal + depositAmt - (reverted ? 0 : withdrawAmt)
        assert(
            (!reverted && afterContractBal + withdrawAmt == beforeContractBal + depositAmt)
            || (reverted && afterContractBal == beforeContractBal + depositAmt)
        );
    }

    // allow receiving Ether so that this contract can fund deposits
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function driving C
    // We avoid calling deposit to not trigger its assert in C; instead we rely on possibility that contract may have nonzero balance
    function run() public payable {
        // Record contract balance before refund
        uint256 beforeContractBal = address(c).balance;

        // Attempt first refund and record whether it reverted
        bool firstReverted;
        try c.refund() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint256 afterFirst = address(c).balance;

        // Attempt second refund to check idempotence: should send zero (not change balance) and not revert
        bool secondReverted;
        try c.refund() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint256 afterSecond = address(c).balance;

        // General rule asserted:
        // - refund should never increase c's balance
        // - if first refund succeeded then contract balance decreased by at least 0 and second refund did not change balance
        // - if first refund reverted then nothing changed and second refund also reverts (both revert or both no-change), but we assert a general invariant:
        //   afterSecond <= afterFirst <= beforeContractBal and afterSecond == afterFirst (second refund doesn't reduce further)
        assert(afterSecond <= afterFirst && afterFirst <= beforeContractBal && afterSecond == afterFirst);
    }

    // Allow receiving Ether from C.transfer during refund
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // run takes an amount to deposit and an amount to attempt to withdraw
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");

        // Read initial observable balances
        uint256 beforeC = address(c).balance;
        uint256 beforeT = address(this).balance;

        // Perform deposit into c from this contract
        c.deposit{value: depositAmount}();

        // Read balance visible via address(c).balance and the contract's visible mapping via calling withdraw attempt outcome
        uint256 afterDepositC = address(c).balance;
        uint256 afterDepositT = address(this).balance;

        // Try to withdraw withdrawAmount from c to this contract; capture whether it reverted
        bool withdrew;
        try c.withdraw(withdrawAmount) {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // Read final balances
        uint256 finalC = address(c).balance;
        uint256 finalT = address(this).balance;

        // General invariant (single assert): Ether is conserved between c and this contract across these operations.
        // i.e., (finalC + finalT) == (beforeC + beforeT + depositAmount)  if withdraw reverted,
        // or equals (beforeC + beforeT + depositAmount - withdrawAmount) if withdraw succeeded.
        assert(
            (withdrew && (finalC + finalT == beforeC + beforeT + depositAmount - withdrawAmount)) ||
            (!withdrew && (finalC + finalT == beforeC + beforeT + depositAmount))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        deployer = msg.sender; // who deployed this test (not used further)
    }

    // callerIsCreator indicates whether this contract should attempt the migrate call
    // to simulate both creator and non-creator cases. We cannot become the original
    // deployer/creator of C here (the checker deploys a fresh C with this contract as creator),
    // so when callerIsCreator==true this contract is the creator of c. When false,
    // we still call from this contract (checker runs single transaction), so migrateTo
    // should revert in that branch.
    function run(bool callerIsCreator, address to) public payable {
        require(to != address(0));

        // record contract balance before call
        uint256 beforeBal = address(c).balance;

        bool reverted;
        // attempt migrateTo; capture revert behavior
        if (callerIsCreator) {
            // In the fresh deployment the checker makes this InvMutTest the creator of c,
            // so this call should NOT revert and should transfer all balance out of c.
            try c.migrateTo(to) {
                reverted = false;
            } catch {
                reverted = true;
            }

            // After a successful migrate by the creator, contract balance must be zero.
            // If it reverted, reverted==true and the second disjunct below allows that.
        } else {
            // If callerIsCreator is false we still call from this contract, but the intent
            // of the property is: when not the creator, migrateTo must revert. We capture
            // that behavior similarly.
            try c.migrateTo(to) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterBal = address(c).balance;

        // General rule: if call did not revert then c.balance becomes zero; if it reverted then
        // c.balance stays unchanged (i.e., equals beforeBal).
        // This captures that only the creator can move all funds out and successful migrate empties c.
        assert((!reverted && afterBal == 0) || (reverted && afterBal == beforeBal));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // callerIsCreator == true means we expect this contract (the deployer of C) to call migrateTo
    function run(bool callerIsCreator, address to) public payable {
        require(to != address(0));

        uint256 beforeBal = address(c).balance;

        bool reverted;
        // perform the migrateTo call as a top-level statement and capture revert
        if (callerIsCreator) {
            try c.migrateTo(to) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.migrateTo(to) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterBal = address(c).balance;

        // General rule: if migrateTo did not revert then contract balance is zero; if it reverted it stays the same
        assert((!reverted && afterBal == 0) || (reverted && afterBal == beforeBal));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: depositAmount to fund c from this contract, withdrawAmount to attempt withdrawal
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        // ensure we can send depositAmount when calling deposit
        require(address(this).balance >= depositAmount);

        // deposit into c from this contract
        c.deposit{value: depositAmount}();

        // read visible recorded balance for this test contract
        uint256 beforeRecorded = c.balances(address(this));
        uint256 beforeActual = address(c).balance;

        bool reverted;
        // attempt withdraw as a top-level statement and capture revert
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterRecorded = c.balances(address(this));
        uint256 afterActual = address(c).balance;

        // General rule: if withdraw did not revert then recorded balance decreased by withdrawAmount and contract balance decreased by at least withdrawAmount; if it reverted both recorded and contract balances are unchanged
        assert((!reverted && afterRecorded + withdrawAmount == beforeRecorded && beforeActual >= withdrawAmount && afterActual + withdrawAmount <= beforeActual) || (reverted && afterRecorded == beforeRecorded && afterActual == beforeActual));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: depositAmount to fund c from this contract, withdrawAmount to attempt withdrawal
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        // ensure this contract can send depositAmount when calling deposit
        require(address(this).balance >= depositAmount);

        // record observable balances before any operations
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // deposit into c from this contract
        c.deposit{value: depositAmount}();

        // balances after deposit and before withdraw
        uint256 midC = address(c).balance;
        uint256 midThis = address(this).balance;

        // midC should have increased by exactly depositAmount
        // (this is a necessary sanity check to make the later rule meaningful)
        // We don't assert it separately; incorporate into the final invariant by using mid values.

        bool reverted;
        // attempt withdraw as a top-level statement and capture revert
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule:
        // If withdraw succeeded then c's balance decreased by exactly withdrawAmount and this contract's balance increased by exactly withdrawAmount.
        // If withdraw reverted then both observable balances are unchanged from just after deposit.
        assert((!reverted && midC >= withdrawAmount && afterC + withdrawAmount == midC && afterThis == midThis + withdrawAmount) || (reverted && afterC == midC && afterThis == midThis));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount to deposit
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        // read balance before
        uint256 beforeAccount = c.balances(address(this));
        uint256 beforeContract = address(c).balance;

        // perform deposit and capture whether it reverted
        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterAccount = c.balances(address(this));
        uint256 afterContract = address(c).balance;

        // If the deposit did not revert then the account balance must increase by exactly amount
        // and the contract's balance must increase by exactly amount.
        assert(reverted || (afterAccount == beforeAccount + amount && afterContract == beforeContract + amount));
    }

    receive() external payable {}
}

