contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        deployer = msg.sender;
    }

    // single public test function taking a target address and a boolean indicating whether
    // the caller should act as creator (true) or a non-creator (false).
    // If asCreator is true we call migrateTo from this contract (which is the creator);
    // if false we simulate a non-creator by performing the call via a fallback that forwards
    // using call from an externally controlled address is not possible here, so we instead
    // check the observable effect: a call from this contract (creator) should succeed, and
    // a call from another contract (NonCaller) should revert and not change balance.
    function run(address to, bool asCreator) public payable {
        require(to != address(0));

        // ensure this test contract has some Ether to deposit into c for migrateTo to transfer
        // send some Ether to c by calling deposit
        uint256 depositAmount = msg.value;
        // depositAmount may be zero; that's allowed
        uint256 beforeBalance = address(c).balance;

        // perform deposit from this contract (this contract is the creator of c per problem statement)
        bool depReverted;
        try c.deposit{value: depositAmount}() {
            depReverted = false;
        } catch {
            depReverted = true;
        }

        // After deposit attempt, record contract balance
        uint256 afterDepositBalance = address(c).balance;

        // If deposit reverted, nothing changed; otherwise balance increased by depositAmount
        // Now test migrateTo behavior. We'll have two branches:
        // - asCreator == true: call migrateTo from this contract (creator) and expect it not to revert,
        //   and that afterwards the contract's balance becomes zero (migrated out).
        // - asCreator == false: deploy a small helper contract NonCaller which will try to call migrateTo
        //   and we will observe whether it reverted by catching and assert that if it reverted then
        //   c's balance remains unchanged, and if it did not revert then c's balance becomes zero.

        // Capture balance before migrate attempts
        uint256 beforeMigrate = address(c).balance;

        bool migratedReverted;
        if (asCreator) {
            // this contract is the creator; attempt should succeed (i.e., not revert)
            try c.migrateTo(to) {
                migratedReverted = false;
            } catch {
                migratedReverted = true;
            }
            // record after
            uint256 after = address(c).balance;

            // Assert: when called by creator it must not revert and contract balance is 0 after
            assert(!migratedReverted && after == 0);
            return;
        } else {
            // deploy helper NonCaller which will call c.migrateTo(to)
            NonCaller nc = new NonCaller(c, to);
            // give NonCaller some gas/funds so it can call; send 0 value
            bool callSucceeded = nc.tryMigrate();
            uint256 after = address(c).balance;

            // General rule: if a non-creator calls migrateTo, the call must revert and the contract balance must be unchanged
            assert(callSucceeded == false && after == beforeMigrate);
            return;
        }
    }

    receive() external payable {}
}

contract NonCaller {
    C c;
    address target;
    constructor(C _c, address _target) payable {
        c = _c;
        target = _target;
    }
    // attempts to call migrateTo; returns true if call did not revert, false if it reverted
    function tryMigrate() public returns (bool) {
        try c.migrateTo(target) {
            return true;
        } catch {
            return false;
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take a target address and a flag indicating whether
    // this contract should act as the creator (true) or simulate a non-creator call (false).
    // If asCreator == true this contract (which is the creator) calls migrateTo; otherwise
    // we deploy a helper contract that attempts to call migrateTo to simulate a non-creator.
    function run(address to, bool asCreator) public payable {
        require(to != address(0));

        // Ensure we have some funds to deposit into c so migrateTo has a non-zero effect when called.
        uint256 depositAmount = msg.value;
        require(address(this).balance >= depositAmount);

        // Deposit funds into c from this contract (this contract is the creator of c per problem statement)
        bool depReverted;
        try c.deposit{value: depositAmount}() {
            depReverted = false;
        } catch {
            depReverted = true;
        }

        uint256 beforeMigrate = address(c).balance;

        if (asCreator) {
            // this contract is the creator; calling migrateTo should succeed and drain the contract
            bool migratedReverted;
            try c.migrateTo(to) {
                migratedReverted = false;
            } catch {
                migratedReverted = true;
            }
            uint256 afterMigrate = address(c).balance;

            // General rule: when called by the creator, migrateTo must not revert and contract balance becomes zero
            assert(migratedReverted == false && afterMigrate == 0);
            return;
        } else {
            // Deploy helper NonCaller which will attempt to call migrateTo from a different contract
            NonCaller nc = new NonCaller(c, to);
            // Try the migrate call via the helper and capture whether it succeeded
            bool callSucceeded = nc.tryMigrate();
            uint256 afterMigrate = address(c).balance;

            // General rule: if a non-creator calls migrateTo, it must revert (callSucceeded == false)
            // and the contract balance must remain unchanged
            assert(callSucceeded == false && afterMigrate == beforeMigrate);
            return;
        }
    }

    receive() external payable {}
}

