    function run(uint256 fund, uint256 wd) public payable {
        // ensure this test contract has Ether to fund c if requested
        if (fund > 0) {
            require(address(this).balance >= fund);
        }

        // If we try to deposit, capture whether it reverted. Avoid calling deposit when fund==0 if it may revert
        bool depositReverted;
        if (fund == 0) {
            // calling deposit with 0 may hit assert in C, so skip the call and treat as reverted for our purposes
            depositReverted = true;
        } else {
            try c.deposit{value: fund}() {
                depositReverted = false;
            } catch {
                depositReverted = true;
            }
        }

        // Read observables before withdraw attempt
        uint256 contractBefore = address(c).balance;
        uint256 recordedBefore = c.balances(address(this));

        // Attempt withdraw and record whether it reverted
        bool withdrawReverted;
        try c.withdraw(wd) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Read observables after withdraw
        uint256 contractAfter = address(c).balance;
        uint256 recordedAfter = c.balances(address(this));

        // General invariant:
        // - If withdraw reverted then both address(c).balance and recorded balance must be unchanged.
        // - If withdraw succeeded then both decreased by the same amount, and that amount is <= recordedBefore.
        // Express without subtraction that can underflow inside assert by using comparisons and equality.
        bool okRevertCase = withdrawReverted && contractAfter == contractBefore && recordedAfter == recordedBefore;

        // For success case, require recordedBefore >= recordedAfter and contractBefore >= contractAfter, and the decreases are equal:
        bool recordedDecreasedOrSame = recordedAfter <= recordedBefore;
        bool contractDecreasedOrSame = contractAfter <= contractBefore;
        // The decrease amounts are (recordedBefore - recordedAfter) and (contractBefore - contractAfter), compare by cross addition to avoid underflow:
        bool equalDecrease = (recordedBefore + contractAfter) == (recordedAfter + contractBefore);

        bool okSuccessCase = (!withdrawReverted) && recordedDecreasedOrSame && contractDecreasedOrSame && equalDecrease;

        // Final asserted general rule: either the revert case holds or the success case holds
        assert(okRevertCase || okSuccessCase);
    }

