        assert(
            refundReverted == true
            || (
                // refund succeeded branch:
                // contract balance did not increase
                afterContractBal <= beforeContractBal
                // and stored balance for this caller is zero as observable by withdraw(1) reverting
                && secondWithdrawReverted == true
            )
        );
    }

    // accept ETH returned by C
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take two amounts: depositAmt to fund the contract for this caller, and withdrawAmt to attempt withdraw.
    // We require this test contract to have ETH to deposit if depositAmt>0.
    function run(uint256 depositAmt, uint256 withdrawAmt) public payable {
        require(address(this).balance >= depositAmt);

        // Try deposit (may revert); record whether deposit succeeded
        bool depositReverted;
        try c.deposit{value: depositAmt}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // Attempt the primary withdraw and record whether it reverted
        bool firstWithdrawReverted;
        try c.withdraw(withdrawAmt) {
            firstWithdrawReverted = false;
        } catch {
            firstWithdrawReverted = true;
        }

        // Probe whether we can still withdraw the same amount after the first withdraw
        bool secondWithdrawReverted;
        try c.withdraw(withdrawAmt) {
            secondWithdrawReverted = false;
        } catch {
            secondWithdrawReverted = true;
        }

        // General rule:
        // If the first withdraw did not revert, then the second withdraw of the same amount must revert
        // (i.e., the caller cannot withdraw the same amount twice successfully), so secondWithdrawReverted == true.
        // If the first withdraw reverted, we make no claim.
        assert(firstWithdrawReverted == true || secondWithdrawReverted == true);
    }

    // accept ETH returned by C
    receive() external payable {}
}

