    constructor(C _c) { c = _c; }

    // params: amount to deposit, amount to withdraw
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount);
        // perform deposit from this test contract
        c.deposit{value: depositAmount}();

        // read balance after deposit for this caller via public getter (balances is private in C, so use behavior: we cannot access it directly)
        // Instead observe address(c).balance and then attempt withdraw and check effects on address(c).balance and this contract balance
        uint256 contractBalBefore = address(c).balance;
        uint256 selfBalBefore = address(this).balance;

        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 contractBalAfter = address(c).balance;
        uint256 selfBalAfter = address(this).balance;

        // General rule: If withdraw did not revert, then the contract's balance decreased by exactly withdrawAmount
        // and this contract's balance increased by exactly withdrawAmount; if withdraw reverted then balances unchanged.
        assert(reverted
               ? (contractBalAfter == contractBalBefore && selfBalAfter == selfBalBefore)
               : (contractBalBefore >= withdrawAmount && contractBalBefore - contractBalAfter == withdrawAmount && selfBalAfter - selfBalBefore == withdrawAmount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: deposit amount to fund the caller's balance, first withdraw amount, second withdraw amount
    function run(uint256 depositAmount, uint256 firstWithdraw, uint256 secondWithdraw) public payable {
        // need Ether to deposit into c
        require(address(this).balance >= depositAmount);
        // make an initial deposit to ensure caller has some recorded balance (avoid triggering C.deposit assert by allowing depositAmount==0)
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // record balances before first withdraw
        uint256 contractBalBefore = address(c).balance;
        uint256 selfBalBefore = address(this).balance;

        bool firstReverted;
        try c.withdraw(firstWithdraw) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint256 contractBalAfterFirst = address(c).balance;
        uint256 selfBalAfterFirst = address(this).balance;

        // Now attempt second withdraw of same or different amount to observe remaining ability to withdraw
        bool secondReverted;
        try c.withdraw(secondWithdraw) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint256 contractBalAfterSecond = address(c).balance;
        uint256 selfBalAfterSecond = address(this).balance;

        // General rule asserted:
        // If first withdraw succeeded then the contract's balance decreased by exactly firstWithdraw
        // and our external balance increased by exactly firstWithdraw; if it reverted then neither changed.
        // Additionally, if the first withdraw succeeded and secondWithdraw equals firstWithdraw and the second withdraw succeeded,
        // then it must be that contract had at least firstWithdraw*2 before any withdraws; otherwise second withdraw should have reverted.
        // We avoid subtraction on stored balances by comparing deltas.
        assert(
            (
                firstReverted
                ? (contractBalAfterFirst == contractBalBefore && selfBalAfterFirst == selfBalBefore)
                : (contractBalBefore >= contractBalAfterFirst && selfBalAfterFirst >= selfBalBefore && contractBalBefore - contractBalAfterFirst == selfBalAfterFirst - selfBalBefore && contractBalBefore - contractBalAfterFirst == firstWithdraw)
            )
            &&
            (
                // If first succeeded and second succeeded and secondWithdraw == firstWithdraw then original contract balance before any withdraws
                // must have been at least firstWithdraw + secondWithdraw. We check this by ensuring contract balance decreased by sum after both.
                (firstReverted || secondReverted || secondWithdraw != firstWithdraw)
                || (
                    // both succeeded and amounts equal: ensure total decrease equals first+second
                    (contractBalBefore >= contractBalAfterSecond && contractBalBefore - contractBalAfterSecond == firstWithdraw + secondWithdraw)
                )
            )
        );
    }

    receive() external payable {}
}

