contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: depositAmount to fund the contract's recorded balance for this caller
    function run(uint256 depositAmount) public payable {
        // Ensure this test contract has enough Ether to perform the deposit if requested
        require(address(this).balance >= depositAmount);

        // Make a deposit to set up a nonzero recorded balance for this caller (may be zero)
        // Do the deposit as a top-level state-changing call
        c.deposit{value: depositAmount}();

        // Observe before-values: this caller's recorded balance cannot be read directly (it's private),
        // but we can observe address(c).balance before the refund and address(this).balance.
        uint256 contractBalBefore = address(c).balance;
        uint256 selfBalBefore = address(this).balance;

        // Call refund and detect whether it reverts
        bool refundedReverted;
        try c.refund() {
            refundedReverted = false;
        } catch {
            refundedReverted = true;
        }

        // Observe after-values
        uint256 contractBalAfter = address(c).balance;
        uint256 selfBalAfter = address(this).balance;

        // General rule:
        // - If refund reverted, no observable balances changed due to refund (contract and caller balances unchanged by the failed call).
        // - If refund succeeded, the contract's balance did not increase (contractBalAfter <= contractBalBefore)
        //   and the caller's recorded balance is zero. We cannot read the private recorded balance directly,
        //   but a necessary observable consequence of recorded balance being zero is that a subsequent withdraw of any
        //   positive amount must revert. So we assert that after a successful refund, any withdraw of 1 wei reverts.

        bool withdraw1RevertedAfterRefund;
        try c.withdraw(1) {
            withdraw1RevertedAfterRefund = false;
        } catch {
            withdraw1RevertedAfterRefund = true;
        }

        assert(
            refundedReverted
            ? (contractBalAfter == contractBalBefore && selfBalAfter == selfBalBefore)
            : (contractBalAfter <= contractBalBefore && selfBalAfter >= selfBalBefore && withdraw1RevertedAfterRefund)
        );
    }

    // Allow receiving Ether from c.transfer
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address creatorProxy;
    constructor(C _c) { c = _c; creatorProxy = address(0); }

    // params:
    // fundAmount: amount this test contract will deposit into c to create nonzero contract balance
    // to: destination address passed to migrateTo
    // callAsCreator: if true, attempt to call migrateTo from the creator by using the test contract (which is the creator of c in the checker setup)
    function run(uint256 fundAmount, address to, bool callAsCreator) public payable {
        // Ensure this contract has enough Ether to fund c if requested
        require(address(this).balance >= fundAmount);

        // Make a deposit as the test contract (which is the creator of c according to the harness description)
        // This is a top-level state-changing call.
        c.deposit{value: fundAmount}();

        // Observe contract balance before migrateTo
        uint256 balBefore = address(c).balance;

        // Decide who will call migrateTo: the checker deploys c and then runs run(...) from the test contract itself.
        // We cannot impersonate other addresses, so to test the non-creator path we attempt to call migrateTo normally
        // but if callAsCreator == false we instead attempt to call migrateTo and expect it to either revert or not change balance.

        bool migratedReverted;
        try c.migrateTo(to) {
            migratedReverted = false;
        } catch {
            migratedReverted = true;
        }

        uint256 balAfter = address(c).balance;

        // General rule asserted:
        // If migrateTo did not revert when called by this contract, then it must have transferred the entire contract balance
        // to the destination (so contract balance is zero after); otherwise (it reverted) the contract balance is unchanged.
        // This captures the intended property that only the creator (which is this contract in the harness) can successfully
        // migrate and a successful migrate drains the contract.
        assert(
            migratedReverted
            ? (balAfter == balBefore)
            : (balAfter == 0)
        );
    }

    // Allow receiving Ether from c.transfer
    receive() external payable {}
}

