    // Params: amount to deposit first, then an amount to attempt to withdraw; both supplied by the fuzzer.
    function run(uint256 depositAmount, uint256 withdrawAmount, bool doRefund) public payable {
        // ensure this test contract has enough Ether to fund the deposit
        require(address(this).balance >= depositAmount);

        // Make an initial deposit so this caller has a positive recorded balance in c
        c.deposit{value: depositAmount}();

        // observe contract balance before the action
        uint256 before = address(c).balance;

        // try either withdraw or refund depending on input; record whether it reverted
        bool reverted;
        if (doRefund) {
            try c.refund() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // observe contract balance after the action
        uint256 after = address(c).balance;

        // General rule:
        // Regardless of success or revert, the caller's recorded balance (as can be observed
        // via effects on contract balance) never increases due to calling withdraw or refund.
        // Concretely: after <= before. If the call reverted then after == before.
        // (This avoids reading private mappings by using address(c).balance observable.)
        assert(after <= before && (reverted ? after == before : true));
    }

    receive() external payable {}
}

